INSERT OR REPLACE INTO nodes (id, parent_id, lane, run_id, trial_id, agent_model, author, title, hypothesis, decision, soft_min_eff, ratio_vs_incumbent, short_horizon_eff, long_horizon_eff, real_stan_passed, real_stan_total, real_ess_per_cost, overhead_ratio, b2_max, dims, codex_refs, code_sha, metrics_json, verified, created_at) VALUES ('A1:real_sim_glm53:T0005', 'A1:real_sim_glm53:T0004', 'A1', 'real_sim_glm53', 'T0005', 'GLM-5.3-Flash', 'GLM-5.3-Flash', 'T0005: With MALA-floor warmup (n=1) the accept target now only shapes the judge''...', 'With MALA-floor warmup (n=1) the accept target now only shapes the judge''s L=2.0 transition: dropping DA target 0.75->0.70 raises final eps ~15% so jittered n=ceil(2/eps) drops one step on banana/hybrid, cutting transition cost/chain ~20% while trajectory distance (ESS driver) is unchanged, giving paired ratio >1.02', 'keep', 0.000805, 1.1404, NULL, NULL, NULL, NULL, NULL, 6.169, 0.08605, NULL, '["fisher-low-rank"]', 'ded198699b39e0e2', '{"archive_cells": ["gaussian_illcond__oh_high", "banana__oh_high", "hybrid_rosenbrock__oh_high", "student_t__oh_high", "mixture_crossable__oh_high"], "ast_sha": "f8c64abf7831a996", "incumbent_soft_min": 0.000706, "judge_digest": "740da459529f66a9", "loc": 159, "seed": 20261508, "tier0_ok": true, "tier1_ok": true, "wall_s": 15.374}', 0, '2026-11-21T12:25:46.897584+00:00');
INSERT OR REPLACE INTO nodes (id, parent_id, lane, run_id, trial_id, agent_model, author, title, hypothesis, decision, soft_min_eff, ratio_vs_incumbent, short_horizon_eff, long_horizon_eff, real_stan_passed, real_stan_total, real_ess_per_cost, overhead_ratio, b2_max, dims, codex_refs, code_sha, metrics_json, verified, created_at) VALUES ('A1:real_sim_glm53:T0006', 'A1:real_sim_glm53:T0005', 'A1', 'real_sim_glm53', 'T0006', 'GLM-5.3-Flash', 'GLM-5.3-Flash', 'T0006: NM-003 retry under a structurally different condition: prior truncation f...', 'NM-003 retry under a structurally different condition: prior truncation failures (W-45/74/77, glm53 T0006) were at HMC warmup with n>1 where late draws carried DA+metric signal; warmup is now MALA-floor (n=1, DA-re-equilibrated eps) so cutting draws 100->70 only removes ~30% billed cost while 49-draw covariance windows and 70-step DA still converge, giving paired ratio >1.02; falsified if funnel/banana ESS collapses', 'keep', 0.000546, 1.5112, NULL, NULL, NULL, NULL, NULL, 6.4, 0.07675, NULL, '["fisher-low-rank"]', '8a653cc77b88e33a', '{"archive_cells": ["funnel__oh_high", "banana__oh_high", "hybrid_rosenbrock__oh_high"], "ast_sha": "7682295cbe74f6e7", "incumbent_soft_min": 0.000362, "judge_digest": "740da459529f66a9", "loc": 159, "seed": 20261605, "tier0_ok": true, "tier1_ok": true, "wall_s": 16.628}', 0, '2026-11-21T12:26:14.807825+00:00');
