INSERT OR REPLACE INTO nodes (id, parent_id, lane, run_id, trial_id, agent_model, author, title, hypothesis, decision, soft_min_eff, ratio_vs_incumbent, short_horizon_eff, long_horizon_eff, real_stan_passed, real_stan_total, real_ess_per_cost, overhead_ratio, b2_max, dims, codex_refs, code_sha, metrics_json, verified, created_at) VALUES ('A1:real_sim_glm53:T0008', 'A1:real_sim_glm53:T0006', 'A1', 'real_sim_glm53', 'T0008', 'GLM-5.3-Flash', 'GLM-5.3-Flash', 'T0008: Under MALA-floor warmup draws are cheap but autocorrelated, so the [0.3w...', 'Under MALA-floor warmup draws are cheap but autocorrelated, so the [0.3w,0.7w) window (28 draws) under-samples the metric; a third pooled update at 0.9w reusing [0.3w,0.9w) (42 draws) adds effective samples at zero billed evals, and the diag part barely moves so the final eps stays calibrated, giving paired ratio >1.02', 'keep', 0.000558, 1.0204, NULL, NULL, NULL, NULL, NULL, 6.269, 0.05667, NULL, '["fisher-low-rank"]', '42a08f62dd5dcd5c', '{"archive_cells": ["gaussian_illcond__oh_high", "hybrid_rosenbrock__oh_high"], "ast_sha": "d8bc71e7bbfced7a", "incumbent_soft_min": 0.000547, "judge_digest": "740da459529f66a9", "loc": 159, "seed": 20261799, "tier0_ok": true, "tier1_ok": true, "wall_s": 20.177}', 0, '2026-11-21T12:27:22.439498+00:00');
INSERT OR REPLACE INTO nodes (id, parent_id, lane, run_id, trial_id, agent_model, author, title, hypothesis, decision, soft_min_eff, ratio_vs_incumbent, short_horizon_eff, long_horizon_eff, real_stan_passed, real_stan_total, real_ess_per_cost, overhead_ratio, b2_max, dims, codex_refs, code_sha, metrics_json, verified, created_at) VALUES ('A1:real_sim_glm53:T0009', 'A1:real_sim_glm53:T0008', 'A1', 'real_sim_glm53', 'T0009', 'GLM-5.3-Flash', 'GLM-5.3-Flash', 'T0009: The hard mode gate (|log eig|>0.30) silently deletes moderate correlation...', 'The hard mode gate (|log eig|>0.30) silently deletes moderate correlation modes that banana/hybrid need; a dense Ledoit-Wolf-shrunk draw covariance keeps all modes with smooth shrinkage (and drops ~20 LOC), improving curved-target ESS at equal cost, giving paired ratio >1.02 or a tie with fewer LOC', 'archive_only', 0.000239, 0.4383, NULL, NULL, NULL, NULL, NULL, 4.679, 0.28159, NULL, '["fisher-low-rank"]', '5833e7b6ef7ca060', '{"archive_cells": ["funnel__oh_med", "banana__oh_med", "hybrid_rosenbrock__oh_med", "student_t__oh_med", "mixture_crossable__oh_med"], "ast_sha": "0d5e74890eff806d", "incumbent_soft_min": 0.000546, "judge_digest": "740da459529f66a9", "loc": 139, "seed": 20261896, "tier0_ok": true, "tier1_ok": true, "wall_s": 26.462}', 0, '2026-11-21T12:28:49.616427+00:00');
INSERT OR REPLACE INTO nodes (id, parent_id, lane, run_id, trial_id, agent_model, author, title, hypothesis, decision, soft_min_eff, ratio_vs_incumbent, short_horizon_eff, long_horizon_eff, real_stan_passed, real_stan_total, real_ess_per_cost, overhead_ratio, b2_max, dims, codex_refs, code_sha, metrics_json, verified, created_at) VALUES ('A1:real_sim_glm53:T0010', 'A1:real_sim_glm53:T0008', 'A1', 'real_sim_glm53', 'T0010', 'GLM-5.3-Flash', 'GLM-5.3-Flash', 'T0010: Variant 2 of keep-moderate-modes (dense LW form failed 0.44x): within the...', 'Variant 2 of keep-moderate-modes (dense LW form failed 0.44x): within the proven whitened-ridge estimator, lowering the hard keep gate 0.30->0.20 retains modes with 20-35% whitened correction that banana/hybrid need, while pooled 42-draw windows and tau=0.35sqrt(r/k) still suppress pure noise, giving paired ratio >1.02', 'archive_only', 0.000518, 0.9975, NULL, NULL, NULL, NULL, NULL, 6.221, 0.15926, NULL, '["fisher-low-rank"]', '8ee6f79679c51f3e', '{"archive_cells": ["gaussian_illcond__oh_high", "funnel__oh_high"], "ast_sha": "205eff6fed946af0", "incumbent_soft_min": 0.000519, "judge_digest": "740da459529f66a9", "loc": 159, "seed": 20261993, "tier0_ok": true, "tier1_ok": true, "wall_s": 19.342}', 0, '2026-11-21T12:29:21.912371+00:00');
INSERT OR REPLACE INTO nodes (id, parent_id, lane, run_id, trial_id, agent_model, author, title, hypothesis, decision, soft_min_eff, ratio_vs_incumbent, short_horizon_eff, long_horizon_eff, real_stan_passed, real_stan_total, real_ess_per_cost, overhead_ratio, b2_max, dims, codex_refs, code_sha, metrics_json, verified, created_at) VALUES ('A1:real_sim_glm53:T0011', 'A1:real_sim_glm53:T0008', 'A1', 'real_sim_glm53', 'T0011', 'GLM-5.3-Flash', 'GLM-5.3-Flash', 'T0011: Probe shows n=ceil(2/eps) keeps trajectory distance ~2.0 at any accept ta...', 'Probe shows n=ceil(2/eps) keeps trajectory distance ~2.0 at any accept target, so ESS is governed by distance+acceptance while cost is n; dropping target 0.70->0.65 lifts hybrid eps 0.77->~0.85 and banana 1.08->~1.2, with n dropping 3->2 or 2->2 at still-decent acceptance, cutting transition cost ~20% for paired ratio >1.02; falsified if accept-rate-driven diffusion loss dominates', 'archive_only', 0.00048, 0.8954, NULL, NULL, NULL, NULL, NULL, 6.401, 0.09105, NULL, '["fisher-low-rank"]', 'ec8277d2d561190b', '{"archive_cells": ["funnel__oh_high", "student_t__oh_high", "mixture_crossable__oh_high"], "ast_sha": "68e8438aec3ed169", "incumbent_soft_min": 0.000536, "judge_digest": "740da459529f66a9", "loc": 159, "seed": 20262090, "tier0_ok": true, "tier1_ok": true, "wall_s": 20.928}', 0, '2026-11-21T12:31:25.250743+00:00');
INSERT OR REPLACE INTO nodes (id, parent_id, lane, run_id, trial_id, agent_model, author, title, hypothesis, decision, soft_min_eff, ratio_vs_incumbent, short_horizon_eff, long_horizon_eff, real_stan_passed, real_stan_total, real_ess_per_cost, overhead_ratio, b2_max, dims, codex_refs, code_sha, metrics_json, verified, created_at) VALUES ('A1:real_sim_glm53:T0012', 'A1:real_sim_glm53:T0008', 'A1', 'real_sim_glm53', 'T0012', 'GLM-5.3-Flash', 'GLM-5.3-Flash', 'T0012: DA init eps0 0.2->0.4 halves the early draws spent climbing from an over...', 'DA init eps0 0.2->0.4 halves the early draws spent climbing from an over-conservative anchor (mu=log(10*eps0)); early identity-metric rejections on stiff targets push DA back down within ~5 steps, while easy targets keep the larger eps longer, netting fewer wasted warmup evals for paired ratio >1.02', 'archive_only', 0.000597, 0.6496, NULL, NULL, NULL, NULL, NULL, 6.525, 0.19386, NULL, '["fisher-low-rank"]', '798177ce1446516a', '{"archive_cells": ["funnel__oh_high", "student_t__oh_high", "mixture_crossable__oh_high"], "ast_sha": "621496373cbdbb19", "incumbent_soft_min": 0.00092, "judge_digest": "740da459529f66a9", "loc": 159, "seed": 20262187, "tier0_ok": true, "tier1_ok": true, "wall_s": 20.849}', 0, '2026-11-21T12:32:04.339318+00:00');
INSERT OR REPLACE INTO nodes (id, parent_id, lane, run_id, trial_id, agent_model, author, title, hypothesis, decision, soft_min_eff, ratio_vs_incumbent, short_horizon_eff, long_horizon_eff, real_stan_passed, real_stan_total, real_ess_per_cost, overhead_ratio, b2_max, dims, codex_refs, code_sha, metrics_json, verified, created_at) VALUES ('A1:real_sim_glm53:T0013', 'A1:real_sim_glm53:T0008', 'A1', 'real_sim_glm53', 'T0013', 'GLM-5.3-Flash', 'GLM-5.3-Flash', 'T0013: The pooled third update mixes draws sampled under the pre-0.7w metric (ha...', 'The pooled third update mixes draws sampled under the pre-0.7w metric (half its 42 draws are off-metric); switching its window to [0.5w,0.9w) keeps ~28 draws that are majority-matched to the final metric, giving a less biased covariance on curved targets for paired ratio >1.02; falsified if the extra sample diversity of [0.3w,0.9w) mattered more', 'archive_only', 0.000615, 1.0077, NULL, NULL, NULL, NULL, NULL, 6.333, 0.11111, NULL, '["fisher-low-rank"]', '3dc6d97f2aec40b0', '{"archive_cells": ["student_t__oh_high", "mixture_crossable__oh_high"], "ast_sha": "328a02fc90434308", "incumbent_soft_min": 0.00061, "judge_digest": "740da459529f66a9", "loc": 159, "seed": 20262284, "tier0_ok": true, "tier1_ok": true, "wall_s": 21.21}', 0, '2026-11-21T12:32:32.660145+00:00');
INSERT OR REPLACE INTO nodes (id, parent_id, lane, run_id, trial_id, agent_model, author, title, hypothesis, decision, soft_min_eff, ratio_vs_incumbent, short_horizon_eff, long_horizon_eff, real_stan_passed, real_stan_total, real_ess_per_cost, overhead_ratio, b2_max, dims, codex_refs, code_sha, metrics_json, verified, created_at) VALUES ('A1:real_sim_glm53:T0014', 'A1:real_sim_glm53:T0008', 'A1', 'real_sim_glm53', 'T0014', 'GLM-5.3-Flash', 'GLM-5.3-Flash', 'T0014: DA''s log_bar eps is calibrated on accepts measured under older, worse met...', 'DA''s log_bar eps is calibrated on accepts measured under older, worse metrics; a 2-transition accept probe at 1.3x eps under the FROZEN final metric reveals headroom, and taking eps_hi when probe accept >= 0.6 discretely drops judge-side n=ceil(2/eps) on hybrid-class targets for a ~15-30% transition-cost cut at ~6 one-time evals, giving paired ratio >1.02', 'archive_only', 0.000476, 0.9706, NULL, NULL, NULL, NULL, NULL, 6.121, 0.09703, NULL, '["fisher-low-rank"]', 'f28abcaea6e70a65', '{"archive_cells": ["banana__oh_high", "student_t__oh_high"], "ast_sha": "32c261ade9337fb7", "incumbent_soft_min": 0.00049, "judge_digest": "740da459529f66a9", "loc": 169, "seed": 20262381, "tier0_ok": true, "tier1_ok": true, "wall_s": 21.394}', 0, '2026-11-21T12:33:47.508990+00:00');
INSERT OR REPLACE INTO nodes (id, parent_id, lane, run_id, trial_id, agent_model, author, title, hypothesis, decision, soft_min_eff, ratio_vs_incumbent, short_horizon_eff, long_horizon_eff, real_stan_passed, real_stan_total, real_ess_per_cost, overhead_ratio, b2_max, dims, codex_refs, code_sha, metrics_json, verified, created_at) VALUES ('A1:real_sim_glm53:T0015', 'A1:real_sim_glm53:T0008', 'A1', 'real_sim_glm53', 'T0015', 'GLM-5.3-Flash', 'GLM-5.3-Flash', 'T0015: At warmup path length 0.1 the staged caps 12/32/64 are dead code (n=ceil(...', 'At warmup path length 0.1 the staged caps 12/32/64 are dead code (n=ceil(0.1/eps) exceeds 12 only when eps<0.0083, which DA never reaches from a 0.2 anchor); collapsing them to a single cap 12 and dropping the unused MAX_RANK constant is behavior-identical, so the paired ratio lands inside the +/-2% tie band and Rule 2.5''s simplicity regularizer should make this a keep_simpler (fewer LOC, fewer magic constants)', 'discard_tier0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["fisher-low-rank"]', '9b7fcfe7c63c06b3', '{"ast_sha": "6369ec89af50af63", "judge_digest": "740da459529f66a9", "loc": 158, "seed": 20262478, "tier0_info": {"checks": [{"adapt_cost": 0.0, "b2_max": Infinity, "max_z": Infinity, "move": 0.0, "passed": false, "reason": "adapt() failed: name ''MAX_RANK'' is not defined", "target": "gaussian_illcond", "z_thresh": 0.0}], "error": "adapt() failed: name ''MAX_RANK'' is not defined", "stage": "invariance_smoke"}, "tier0_ok": false, "tier1_ok": false, "wall_s": 0.702}', 0, '2026-11-21T12:34:08.240498+00:00');
INSERT OR REPLACE INTO nodes (id, parent_id, lane, run_id, trial_id, agent_model, author, title, hypothesis, decision, soft_min_eff, ratio_vs_incumbent, short_horizon_eff, long_horizon_eff, real_stan_passed, real_stan_total, real_ess_per_cost, overhead_ratio, b2_max, dims, codex_refs, code_sha, metrics_json, verified, created_at) VALUES ('A1:real_sim_glm53:T0016', 'A1:real_sim_glm53:T0008', 'A1', 'real_sim_glm53', 'T0016', 'GLM-5.3-Flash', 'GLM-5.3-Flash', 'T0016: T0016 = T0015 retry with the still-referenced MAX_RANK constant restored...', 'T0016 = T0015 retry with the still-referenced MAX_RANK constant restored: staged caps 12/32/64 -> single 12 (dead code at path length 0.1), so paired ratio stays inside the +/-2% tie band and the simplicity regularizer converts the tie into keep_simpler (one less branch, two fewer magic constants)', 'archive_only', 0.000483, 1.0, NULL, NULL, NULL, NULL, NULL, 6.414, 0.19335, NULL, '["fisher-low-rank"]', '43f6b319bf8167e9', '{"archive_cells": ["gaussian_illcond__oh_high", "funnel__oh_high", "banana__oh_high", "student_t__oh_high", "mixture_crossable__oh_high"], "ast_sha": "1d350bc615a02ca3", "incumbent_soft_min": 0.000483, "judge_digest": "740da459529f66a9", "loc": 159, "seed": 20262575, "tier0_ok": true, "tier1_ok": true, "wall_s": 21.482}', 0, '2026-11-21T12:34:40.449022+00:00');
INSERT OR REPLACE INTO nodes (id, parent_id, lane, run_id, trial_id, agent_model, author, title, hypothesis, decision, soft_min_eff, ratio_vs_incumbent, short_horizon_eff, long_horizon_eff, real_stan_passed, real_stan_total, real_ess_per_cost, overhead_ratio, b2_max, dims, codex_refs, code_sha, metrics_json, verified, created_at) VALUES ('A1:real_sim_glm53:T0017', 'A1:real_sim_glm53:T0008', 'A1', 'real_sim_glm53', 'T0017', 'GLM-5.3-Flash', 'GLM-5.3-Flash', 'T0017: T0017: same dead-code cap collapse as T0016 but inlined (w_cap line delet...', 'T0017: same dead-code cap collapse as T0016 but inlined (w_cap line deleted), giving strictly fewer LOC than the incumbent so the measured tie inside the +/-2% band converts to keep_simpler under the simplicity regularizer', 'keep_simpler', 0.000794, 1.0, NULL, NULL, NULL, NULL, NULL, 6.373, 0.06668, NULL, '["fisher-low-rank"]', 'd882dd3af7af1ca1', '{"archive_cells": [], "ast_sha": "f4572cd84d633f4c", "incumbent_soft_min": 0.000794, "judge_digest": "740da459529f66a9", "loc": 158, "seed": 20262672, "tier0_ok": true, "tier1_ok": true, "wall_s": 20.631}', 0, '2026-11-21T12:35:16.628278+00:00');
INSERT OR REPLACE INTO nodes (id, parent_id, lane, run_id, trial_id, agent_model, author, title, hypothesis, decision, soft_min_eff, ratio_vs_incumbent, short_horizon_eff, long_horizon_eff, real_stan_passed, real_stan_total, real_ess_per_cost, overhead_ratio, b2_max, dims, codex_refs, code_sha, metrics_json, verified, created_at) VALUES ('A1:real_sim_glm53:T0018', 'A1:real_sim_glm53:T0017', 'A1', 'real_sim_glm53', 'T0018', 'GLM-5.3-Flash', 'GLM-5.3-Flash', 'T0018: Lighter diagonal shrinkage k/(k+5)->k/(k+3): the 1e-3 prior floor biases...', 'Lighter diagonal shrinkage k/(k+5)->k/(k+3): the 1e-3 prior floor biases small-variance coordinates on scaled targets (hybrid block scales span 2 orders); with 28-42-draw windows the estimator is accurate enough that less shrinkage sharpens the diagonal on hybrid/banana for paired ratio >1.02; falsified if noise inflation on small windows dominates', 'keep', 0.000733, 1.3634, NULL, NULL, NULL, NULL, NULL, 6.368, 0.16535, NULL, '["fisher-low-rank"]', '2f61e3c096bab8e6', '{"archive_cells": ["gaussian_illcond__oh_high", "banana__oh_high", "student_t__oh_high"], "ast_sha": "93f58e19d0ca4df0", "incumbent_soft_min": 0.000538, "judge_digest": "740da459529f66a9", "loc": 158, "seed": 20262769, "tier0_ok": true, "tier1_ok": true, "wall_s": 21.459}', 0, '2026-11-21T12:36:15.968542+00:00');
INSERT OR REPLACE INTO nodes (id, parent_id, lane, run_id, trial_id, agent_model, author, title, hypothesis, decision, soft_min_eff, ratio_vs_incumbent, short_horizon_eff, long_horizon_eff, real_stan_passed, real_stan_total, real_ess_per_cost, overhead_ratio, b2_max, dims, codex_refs, code_sha, metrics_json, verified, created_at) VALUES ('A1:real_sim_glm53:T0019', 'A1:real_sim_glm53:T0018', 'A1', 'real_sim_glm53', 'T0019', 'GLM-5.3-Flash', 'GLM-5.3-Flash', 'T0019: Continue shrinkage ladder to k/(k+2): windows now hold 28-42 draws so est...', 'Continue shrinkage ladder to k/(k+2): windows now hold 28-42 draws so estimator noise is low enough that near-unweighted diagonal wins on scaled targets; falsified if tier-0 smoke or rotated-Gaussian z-gates trip on estimator noise', 'archive_only', 0.000253, 0.4437, NULL, NULL, NULL, NULL, NULL, 6.405, 0.14062, NULL, '["fisher-low-rank"]', 'af4359de075a3c6e', '{"archive_cells": ["banana__oh_high", "hybrid_rosenbrock__oh_high", "mixture_crossable__oh_high"], "ast_sha": "0db598fdf3fd8817", "incumbent_soft_min": 0.00057, "judge_digest": "740da459529f66a9", "loc": 158, "seed": 20262866, "tier0_ok": true, "tier1_ok": true, "wall_s": 18.225}', 0, '2026-11-21T12:36:40.300323+00:00');
INSERT OR REPLACE INTO nodes (id, parent_id, lane, run_id, trial_id, agent_model, author, title, hypothesis, decision, soft_min_eff, ratio_vs_incumbent, short_horizon_eff, long_horizon_eff, real_stan_passed, real_stan_total, real_ess_per_cost, overhead_ratio, b2_max, dims, codex_refs, code_sha, metrics_json, verified, created_at) VALUES ('A1:real_sim_glm53:T0020', 'A1:real_sim_glm53:T0018', 'A1', 'real_sim_glm53', 'T0020', 'GLM-5.3-Flash', 'GLM-5.3-Flash', 'T0020: Generalization check (not a ratchet trial): the incumbent''s MALA-floor wa...', 'Generalization check (not a ratchet trial): the incumbent''s MALA-floor warmup + pooled windows + k/(k+3) shrinkage should hold or improve at dim=12 where whitened mode-gating has more modes to prune; paired ratio >1.02 confirms the win is not dim=6-specific', 'discard_duplicate', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["fisher-low-rank"]', '2f61e3c096bab8e6', '{"ast_sha": "93f58e19d0ca4df0", "judge_digest": "740da459529f66a9", "loc": 158, "seed": 20262963, "tier0_ok": false, "tier1_ok": false, "wall_s": 0.0}', 0, '2026-11-21T12:37:00.700325+00:00');
INSERT OR REPLACE INTO nodes (id, parent_id, lane, run_id, trial_id, agent_model, author, title, hypothesis, decision, soft_min_eff, ratio_vs_incumbent, short_horizon_eff, long_horizon_eff, real_stan_passed, real_stan_total, real_ess_per_cost, overhead_ratio, b2_max, dims, codex_refs, code_sha, metrics_json, verified, created_at) VALUES ('A1:real_sim_glm53:T0021', 'A1:real_sim_glm53:T0018', 'A1', 'real_sim_glm53', 'T0021', 'GLM-5.3-Flash', 'GLM-5.3-Flash', 'T0021: GENERALIZATION CHECK at dim=12, roles reversed: candidate = session-START...', 'GENERALIZATION CHECK at dim=12, roles reversed: candidate = session-STARTING submission (main incumbent, L=2.0 Fisher geometric-mean form) vs current lane incumbent (MALA-floor warmup + pooled windows + k/(k+3)); expect ratio well below 1.0 if the session''s wins generalize beyond dim=6, ~1.0 if they are dim=6-specific', 'discard_no_gain', 5.5e-05, 0.399, NULL, NULL, NULL, NULL, NULL, 3.739, 0.28159, NULL, '["fisher-low-rank"]', '55a02b88bbba03fb', '{"archive_cells": [], "ast_sha": "376d99951a25a12d", "incumbent_soft_min": 0.000137, "judge_digest": "740da459529f66a9", "loc": 159, "seed": 20263060, "tier0_ok": true, "tier1_ok": true, "wall_s": 28.957}', 0, '2026-11-21T12:37:44.550242+00:00');
INSERT OR REPLACE INTO nodes (id, parent_id, lane, run_id, trial_id, agent_model, author, title, hypothesis, decision, soft_min_eff, ratio_vs_incumbent, short_horizon_eff, long_horizon_eff, real_stan_passed, real_stan_total, real_ess_per_cost, overhead_ratio, b2_max, dims, codex_refs, code_sha, metrics_json, verified, created_at) VALUES ('A1:real_sim_glm53:T0022', 'A1:real_sim_glm53:T0018', 'A1', 'real_sim_glm53', 'T0022', 'GLM-5.3-Flash', 'GLM-5.3-Flash', 'T0022: GENERALIZATION CHECK at dim=3, roles reversed: candidate = session-STARTI...', 'GENERALIZATION CHECK at dim=3, roles reversed: candidate = session-STARTING submission vs current incumbent; expect ratio well below 1.0 if the MALA-floor/pooled-window wins hold in low dimension too', 'discard_duplicate', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["fisher-low-rank"]', '55a02b88bbba03fb', '{"ast_sha": "376d99951a25a12d", "judge_digest": "740da459529f66a9", "loc": 159, "seed": 20263157, "tier0_ok": false, "tier1_ok": false, "wall_s": 0.0}', 0, '2026-11-21T12:41:04.651649+00:00');
