INSERT OR REPLACE INTO nodes (id, parent_id, lane, run_id, trial_id, agent_model, author, title, hypothesis, decision, soft_min_eff, ratio_vs_incumbent, short_horizon_eff, long_horizon_eff, real_stan_passed, real_stan_total, real_ess_per_cost, overhead_ratio, b2_max, dims, codex_refs, code_sha, metrics_json, verified, created_at) VALUES ('A1:real_sim_glm53:T0024', 'A1:real_sim_glm53:T0018', 'A1', 'real_sim_glm53', 'T0024', 'GLM-5.3-Flash', 'GLM-5.3-Flash', 'T0024: NM-007 retry condition exactly as scoped: replace the constant 1e-3 shrin...', 'NM-007 retry condition exactly as scoped: replace the constant 1e-3 shrinkage floor with the geometric mean of the per-coordinate variances (scale-free), so targets whose scales span orders of magnitude (hybrid blocks, illcond eigenvalues) no longer have small-variance coordinates pulled toward an arbitrary absolute scale; paired ratio >1.02 or the NM-007 boundary stands', 'discard_duplicate', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["fisher-low-rank"]', '2f61e3c096bab8e6', '{"ast_sha": "93f58e19d0ca4df0", "judge_digest": "740da459529f66a9", "loc": 158, "seed": 20263351, "tier0_ok": false, "tier1_ok": false, "wall_s": 0.0}', 0, '2026-11-21T12:42:37.870016+00:00');
