INSERT OR REPLACE INTO nodes (id, parent_id, lane, run_id, trial_id, agent_model, author, title, hypothesis, decision, soft_min_eff, ratio_vs_incumbent, short_horizon_eff, long_horizon_eff, real_stan_passed, real_stan_total, real_ess_per_cost, overhead_ratio, b2_max, dims, codex_refs, code_sha, metrics_json, verified, created_at) VALUES ('A1:real_sim_glm53:T0026', 'A1:real_sim_glm53:T0018', 'A1', 'real_sim_glm53', 'T0026', 'GLM-5.3-Flash', 'GLM-5.3-Flash', 'T0026: Ablation: the 0.3w metric update is transient (superseded at 0.7w) and on...', 'Ablation: the 0.3w metric update is transient (superseded at 0.7w) and only exists to help early warmup mixing + anchor the DA restart; under MALA-floor warmup early draws are cheap (n=1) so the identity-metric phase costs little, and removing the update deletes the DA restart noise, giving paired ratio >1.02; falsified if early identity-metric wandering corrupts the [0.3w,0.9w) pooled window', 'keep', 0.000846, 1.07, NULL, NULL, NULL, NULL, NULL, 5.973, 0.08987, NULL, '["fisher-low-rank"]', 'c642e30689305766', '{"archive_cells": ["gaussian_illcond__oh_high", "banana__oh_high", "student_t__oh_high"], "ast_sha": "54ab20042554123b", "incumbent_soft_min": 0.000791, "judge_digest": "740da459529f66a9", "loc": 158, "seed": 20263545, "tier0_ok": true, "tier1_ok": true, "wall_s": 20.673}', 0, '2026-11-21T12:43:41.657565+00:00');
